{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "items",
      "type": "TreeListItemData[]",
      "description": "Recursive tree item data with id, label, optional children and isExpanded, plus optional xstyle, className, and style applied to that item row.",
      "required": true
    },
    {
      "name": "density",
      "type": "'compact' | 'balanced' | 'spacious'",
      "description": "Spacing density for items.",
      "default": "'balanced'"
    },
    {
      "name": "variant",
      "type": "'lineGuides' | 'noGuides'",
      "description": "Visual treatment of the hierarchy guide lines. lineGuides shows connector lines; noGuides hides them, keeping indentation. Orthogonal to density.",
      "default": "'lineGuides'"
    },
    {
      "name": "animatedLayout",
      "type": "AnimatedLayout",
      "description": "The handle from useAnimatedLayout({containerRef}). With it, expanding or collapsing a row glides the rows and content after it, up to that container, on one shared motion role instead of jumping, and the shown rows and the chevron move on the same motion. Without it, the content after the row takes its place at once."
    },
    {
      "name": "header",
      "type": "ReactNode",
      "description": "Header content, associated with the tree via aria-labelledby.",
      "slotElements": [
        {
          "__element": "Text",
          "props": {
            "type": "body"
          },
          "children": "Header"
        }
      ]
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization. Must be a stylex.create() value."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
